import{b as i,O as t,g as a,j as e}from"./chunks/framework.DcaUmd3X.js";const c=JSON.parse('{"title":"SELECT入门","description":"","frontmatter":{},"headers":[],"relativePath":"database/mysql/query/select-basics/index.md","filePath":"数据库管理/MySQL必知必会/2.数据查询/01.SELECT入门.md","lastUpdated":1782225202000}'),l={name:"database/mysql/query/select-basics/index.md"};function n(h,s,d,p,k,r){return t(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="select入门" tabindex="-1">SELECT入门 <a class="header-anchor" href="#select入门" aria-label="Permalink to &quot;SELECT入门&quot;">​</a></h1><blockquote><p>检索数据、去重、限制行数、写注释</p></blockquote><h2 id="一条最简单的-select" tabindex="-1">一条最简单的 SELECT <a class="header-anchor" href="#一条最简单的-select" aria-label="Permalink to &quot;一条最简单的 SELECT&quot;">​</a></h2><p>假设你有一张 <code>users</code> 表，里面有 id、name、age、city、salary 五列。现在想看一眼所有人的名字，怎么写？</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users;</span></span></code></pre></div><p>这就是最核心的 SQL 语法：<strong><code>SELECT 列名 FROM 表名</code></strong>。</p><ul><li><code>SELECT</code> — 告诉 MySQL &quot;我要查东西&quot;</li><li><code>name</code> — 要查的列</li><li><code>FROM users</code> — 从哪张表里查</li></ul><p>结果：</p><table tabindex="0"><thead><tr><th>name</th></tr></thead><tbody><tr><td>张三</td></tr><tr><td>李四</td></tr><tr><td>王五</td></tr><tr><td>...</td></tr></tbody></table><p>简单到不需要更多解释。接下来我们在这句话的基础上逐步加料。</p><h2 id="检索多列" tabindex="-1">检索多列 <a class="header-anchor" href="#检索多列" aria-label="Permalink to &quot;检索多列&quot;">​</a></h2><p>想一次查名字和年龄？列名之间用逗号隔开：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, age </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>name</th><th>age</th></tr></thead><tbody><tr><td>张三</td><td>25</td></tr><tr><td>李四</td><td>30</td></tr><tr><td>王五</td><td>28</td></tr><tr><td>...</td><td>...</td></tr></tbody></table><p>列的顺序完全由你定，想怎么排就怎么排：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> city, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, salary </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users;</span></span></code></pre></div><blockquote><p>💡 <strong>注意</strong>：最后一个列名后面不要加逗号，<code>SELECT name, age, FROM users</code> 会报错。</p></blockquote><h2 id="检索所有列" tabindex="-1">检索所有列 <a class="header-anchor" href="#检索所有列" aria-label="Permalink to &quot;检索所有列&quot;">​</a></h2><p>懒人专属——不想敲列名就用 <code>*</code>：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users;</span></span></code></pre></div><p><code>*</code> 是通配符，代表&quot;所有列，按表定义的顺序返回&quot;。</p><p><strong>优点</strong>：省事，不知道有什么列时可以先用 <code>*</code> 看一眼。</p><p><strong>坑</strong>：</p><ul><li>表有 100 列但只需要 3 列，<code>*</code> 也会把所有列都捞出来，浪费传输</li><li>表的列顺序变了，代码可能会出问题</li></ul><blockquote><p>⚠️ <strong>生产环境少用 <code>SELECT *</code></strong>，写代码时明确指定需要的列，后期维护会少很多麻烦。</p></blockquote><h2 id="去掉重复行-distinct" tabindex="-1">去掉重复行：DISTINCT <a class="header-anchor" href="#去掉重复行-distinct" aria-label="Permalink to &quot;去掉重复行：DISTINCT&quot;">​</a></h2><p>查一下公司员工都在哪些城市：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> city </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>city</th></tr></thead><tbody><tr><td>北京</td></tr><tr><td>上海</td></tr><tr><td>广州</td></tr><tr><td>深圳</td></tr><tr><td>北京</td></tr><tr><td>上海</td></tr><tr><td>杭州</td></tr><tr><td>北京</td></tr></tbody></table><blockquote><p>北京出现了 3 次，上海 2 次</p></blockquote><p>8 个人但只分布在 5 个城市，&quot;北京&quot;出现了 3 次。想去掉重复，加一个 <code>DISTINCT</code>：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT DISTINCT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> city </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>city</th></tr></thead><tbody><tr><td>北京</td></tr><tr><td>上海</td></tr><tr><td>广州</td></tr><tr><td>深圳</td></tr><tr><td>杭州</td></tr></tbody></table><p>干净了。</p><blockquote><p>⚠️ <code>DISTINCT</code> 作用于<strong>所有列的组合</strong>。<code>SELECT DISTINCT city, name</code> 的意思是&quot;城市 + 名字的组合不重复&quot;，不是&quot;只看城市不重复&quot;。</p></blockquote><h2 id="只要前n行-limit" tabindex="-1">只要前N行：LIMIT <a class="header-anchor" href="#只要前n行-limit" aria-label="Permalink to &quot;只要前N行：LIMIT&quot;">​</a></h2><p>表里有 8 行，暂时只想看前 3 行？</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, age </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIMIT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>name</th><th>age</th></tr></thead><tbody><tr><td>张三</td><td>25</td></tr><tr><td>李四</td><td>30</td></tr><tr><td>王五</td><td>28</td></tr></tbody></table><p>还可以指定从第几行开始拿。比如从第 4 行开始，拿 2 行：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, age </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIMIT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><ul><li><code>3</code> — 跳过前 3 行（行号从 0 开始计数，所以跳过的是 0、1、2）</li><li><code>2</code> — 取 2 行</li></ul><table tabindex="0"><thead><tr><th>name</th><th>age</th></tr></thead><tbody><tr><td>赵六</td><td>35</td></tr><tr><td>孙七</td><td>22</td></tr></tbody></table><p>MySQL 也支持另一种更直观的写法（推荐）：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, age </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIMIT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OFFSET </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p><code>LIMIT 2 OFFSET 3</code> — 跳过 3 行，取 2 行。含义一目了然。</p><blockquote><p>💡 分页查询就是靠 <code>LIMIT</code> 实现的。比如每页 10 条，第 1 页 <code>LIMIT 0, 10</code>，第 2 页 <code>LIMIT 10, 10</code>，第 3 页 <code>LIMIT 20, 10</code>……</p></blockquote><h2 id="使用注释" tabindex="-1">使用注释 <a class="header-anchor" href="#使用注释" aria-label="Permalink to &quot;使用注释&quot;">​</a></h2><p>写复杂 SQL 时，加注释是给自己和别人看的备忘录。MySQL 支持两种注释：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 这是单行注释，查询北京的用户</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, city</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> city </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;北京&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- WHERE 后面会讲，先不纠结</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/*</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  这是多行注释</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  可以写很多行</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  2024年6月13日 张三写的</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">*/</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT DISTINCT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> city </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users;</span></span></code></pre></div><p>如果想让 MySQL <strong>完全不执行</strong>某条语句但不删除它，注释掉就行——调试时常用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这章学会了最核心的 SQL 操作——查数据，记住五件事：</p><ol><li><strong><code>SELECT 列 FROM 表</code></strong> — 检索的固定句式，列用逗号隔开</li><li><strong><code>DISTINCT</code> 去重</strong> — 作用于所有列的组合，不是只看第一列</li><li><strong><code>LIMIT</code> 控制行数</strong> — 分页就是靠它，<code>LIMIT N OFFSET M</code> 最直观</li><li><strong><code>SELECT *</code> 慎用</strong> — 快速看一眼可以，写代码时明确指定列</li><li><strong>注释是好习惯</strong> — <code>--</code> 单行，<code>/* */</code> 多行，复杂 SQL 给自己留备忘</li></ol><blockquote><p>💡 SELECT 是整个 SQL 的根基，后面所有章节都是在这句话上加料。把上面五个操作跑熟了，下一章加筛选条件。</p></blockquote><h2 id="自主练习" tabindex="-1">自主练习 <a class="header-anchor" href="#自主练习" aria-label="Permalink to &quot;自主练习&quot;">​</a></h2><p>用 <code>users</code> 表试试这些操作：</p><ol><li>查询所有员工的 id、name、salary 三列</li><li>查询公司都在哪些城市有员工（不重复）</li><li>查询前 5 个员工的全部信息</li><li>从第 3 个开始，往后查 4 个人</li></ol><p>答案自己跑跑看～下一章我们学习怎么加条件筛选，比如&quot;查所有北京的员工&quot;。</p>`,59)])])}const E=i(l,[["render",n]]);export{c as __pageData,E as default};
